### FUNCION: handleDragStart
```js
function handleDragStart(e, cardId) {
    const card = document.getElementById(cardId);
    if (!card) return;

    // Añadir clase de arrastre y almacenar el ID en el dataTransfer
    card.classList.add('dragging');
    e.dataTransfer.setData('text/plain', cardId);
    e.dataTransfer.effectAllowed = 'move';
}
```

### FUNCION: handleDragOver
```js
function handleDragOver(e) {
    e.preventDefault(); // Permite el drop
    const targetCol = e.currentTarget;
    if (!targetCol || !targetCol.querySelector('.card-container')) return;

    // Determinar si estamos sobre un contenedor de tarjetas o en un área vacía
    const container = targetCol.querySelector('.card-container');
    if (container) {
        e.dataTransfer.dropEffect = 'move';
    } else {
        e.dataTransfer.dropEffect = 'none';
    }
}
```

### FUNCION: handleDrop
```js
function handleDrop(e, targetColId) {
    e.preventDefault();
    const data = e.dataTransfer.getData('text/plain');
    if (!data) return;

    // 1. Eliminar la clase de arrastre del elemento original (si existe)
    const draggedCard = document.getElementById(data);
    if (draggedCard) {
        draggedCard.classList.remove('dragging');
    }

    // 2. Encontrar el contenedor objetivo y manejar la lógica de drop
    const targetContainer = document.getElementById(`cards-${targetColId}`);
    if (!targetContainer) return;

    // Lógica para mover el elemento DOM
    let draggedElement = document.querySelector(`.card[data-card-id="${data}"]`);
    if (draggedElement && draggedElement.parentNode !== targetContainer) {
        // Si está en otra columna, lo movemos y actualizamos su ID de contenedor
        targetContainer.appendChild(draggedElement);
        draggedElement.dataset.columnId = targetColId; // Actualizar el atributo de la columna
    } else if (draggedElement && draggedElement.parentNode === targetContainer) {
        // Si ya está en el contenedor, solo lo reordenamos si es necesario (aunque esto no debería pasar con drag&drop estándar)
    }

    // 3. Actualizar contadores y estado visual
    updateCounters();
    renderCardsToContainer(targetColId, targetContainer); // Re-renderiza para asegurar que el DOM esté limpio y actualizado
}
```

